import './style.css';
import { icon, emblem } from './icons.js';
import { roles, planets, categories, getItem, allItems } from './catalog.js';
import { STORAGE_KEY, LEGACY_KEY, initialState, createAlliance, uid, integer, text, allianceLevel, xpProgress, getAlliance, log, adjustResource, recordEventResults, updateBonusLevels, updateInterface, addPlanetRecord, claimOutpostBonus, removePlanetRecord, grantItem, owned, purchase, craft, removeInventory, updateSettings, validateState } from './model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n).toLocaleString('ru-RU');
const SITE_NAME='Космический корабль Генезис';
const app=document.querySelector('#app');
let state,storageProblem=false,hasLegacy=false;
try { state=app.dataset.snapshot?JSON.parse(app.dataset.snapshot):initialState(); if(!validateState(state))throw Error(); } catch { state=initialState(); }
try { hasLegacy=!!localStorage.getItem(LEGACY_KEY); } catch {}
let auth={role:'viewer',configured:false},serverReady=false,revision=0,busy=false;
const readActions=new Set(['noop','close','menu','login','logout','selectAlliance','activate','openPlanet','planetTab','equipmentTab','catalogFilter','item','inventory','gotoEquipment','export','downloadSnapshot']);
const isAdmin=()=>serverReady&&auth.role==='admin';
let page='overview',activeId=state.alliances[0]?.id||'',planet='cadia',equipmentTab='equipment',search='',catalogFilter='all';
const nav=[['overview','grid','Обзор'],['alliances','people','Альянсы'],['planets','orbit','Планеты'],['interface','bolt','Интерфейс'],['access','key','Доступ'],['upgrades','trending','Прокачка'],['equipment','box','Эквип'],['history','clock','Хроника']];
const active=()=>state.alliances.find(a=>a.id===activeId);
const match=t=>String(t).toLowerCase().includes(search.toLowerCase());
function toast(message,error=false){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className=`toast ${error?'error':''}`;el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),4500);}
async function api(path,options={}) {
 const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(auth.csrfToken?{'X-CSRF-Token':auth.csrfToken}:{}),...options.headers}});
 let data;try{data=await response.json();}catch{throw Error('Сервер недоступен. Изменения не сохранены.');}
 if(!response.ok){const err=Error(data.error||'Сервер не смог выполнить запрос.');err.status=response.status;throw err;}return data;
}
async function save() {
 if(!isAdmin())throw Error('Изменять данные может только администратор.');
 const result=await api('/api/state',{method:'PUT',body:JSON.stringify({state,revision})});revision=result.revision;
}
async function refreshRemote(first=false) {
 if(location.protocol==='file:'||busy||(!first&&document.querySelector('#modal')?.open))return;
 try{
  const [session,data]=await Promise.all([api('/api/session'),api('/api/state')]);
  if(!validateState(data.state))throw Error('Некорректные данные сервера.');
  const changed=!serverReady||revision!==data.revision||session.role!==auth.role;
  auth=session;serverReady=true;
  if(changed||first){state=data.state;revision=data.revision;render();}
 }catch{if(first){serverReady=false;auth={role:'viewer',configured:false};render();}else if(isAdmin()){toast('Связь с сервером потеряна. Изменения сохранятся только после восстановления связи.',true);}}
}
function loginModal(){
 if(!serverReady){modal('Вход недоступен',intro('Это HTML-копия для просмотра. Вход администратора доступен на сайте, подключённом к серверу.'));return;}
 if(!auth.configured){modal('Вход пока не настроен',intro('Владелец сайта должен задать пароль администратора в защищённых настройках хостинга.'));return;}
 modal('Вход организатора',`${intro('Войдите, чтобы изменять прогресс смены. Остальным пользователям доступен только просмотр.')}<form data-form="login">${field('Пароль администратора',input('password','','type="password" autocomplete="current-password" maxlength="256" required'))}${submit('Войти')}</form>`);
}
function applyAccessControls(){
 const d=app.querySelector('#modal');
 app.querySelectorAll('[data-action]').forEach(el=>{if(isAdmin()||readActions.has(el.dataset.action))return;if(el.classList.contains('function-card')){el.removeAttribute('data-action');el.disabled=true;el.querySelector('small')?.remove();}else el.hidden=true;});
 if(!isAdmin())app.querySelector('.daily-callout')?.remove();
}
function navigate(id){page=id;search='';catalogFilter='all';render();window.scrollTo(0,0);}
const button=(label,action,cls='secondary',attrs='')=>!isAdmin()&&!readActions.has(action)?'':`<button class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const empty=(title,note,action='')=>`<div class="empty">${icon('orbit')}<h2>${title}</h2><p>${note}</p>${action}</div>`;
const allianceOptions=(id=activeId)=>state.alliances.map(a=>`<option value="${a.id}" ${a.id===id?'selected':''}>${esc(a.name)}</option>`).join('');
function render(){
 if(!state.alliances.some(a=>a.id===activeId))activeId=state.alliances[0]?.id||'';
 document.title=SITE_NAME;
 const titles={overview:'Прогресс альянсов',alliances:'Альянсы',planets:'Планеты',interface:'Интерфейсы',access:'Доступ',upgrades:'Прокачка',equipment:'Эквип',history:'Хроника'};
 const descriptions={overview:'Крышечки, опыт и уровни всех альянсов.',alliances:'Показатели, участники и владения выбранного альянса.',planets:'Аванпосты Кадии, исследования Фенриса и шаттлы Кронуса.',interface:'Заряд, гравитоны и стойкость.',access:'Особые возможности за крышечки.',upgrades:'Улучшения альянса: цена, эффект и крафт.',equipment:'Предметы, способности и инструменты.',history:'Награды за мероприятия и история изменений.'};
 app.innerHTML=`<aside class="sidebar">
  <a href="#overview" class="brand" aria-label="${SITE_NAME} — обзор"><span class="brand-mark">${icon('rocket')}</span><span class="brand-copy"><span>Космический корабль</span><strong>Генезис</strong></span></a>
  <button class="shift-switcher" data-action="${isAdmin()?'settings':'noop'}" ${isAdmin()?'':'disabled'}><span class="shift-symbol">${icon('settings')}</span><span><strong>${esc(state.shift.name)}</strong><small>${isAdmin()?'Настройки смены':'Текущая смена'}</small></span>${isAdmin()?icon('down'):''}</button>
  <nav aria-label="Разделы сайта">${nav.map(([id,i,label])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</nav>
 </aside><div class="main-shell"><header class="topbar">
  <button class="icon-button mobile-menu" aria-label="Открыть меню" data-action="menu">${icon('menu')}</button>
  <div class="breadcrumb"><strong class="desktop-section">${nav.find(n=>n[0]===page)[2]}</strong><span class="mobile-site-name">Космический корабль<b>Генезис</b></span></div>
  <div class="top-actions"><span class="sol-label">Сол ${state.shift.day} / ${state.shift.duration}</span><span class="top-divider"></span><label class="active-alliance"><span>Альянс</span><select id="active-alliance" aria-label="Активный альянс">${state.alliances.length?allianceOptions():'<option value="">Нет альянсов</option>'}</select></label>${button(isAdmin()?'Выйти':'Вход организатора',isAdmin()?'logout':'login','ghost auth-button')}</div>
 </header><main>
  <div class="page-heading"><div><div class="access-banner ${isAdmin()?'admin':'viewer'}">${icon(isAdmin()?'key':'shield')}<span>${serverReady?(isAdmin()?'Организатор':'Только просмотр'):'Копия для просмотра'}</span></div><h1>${titles[page]}</h1><p>${descriptions[page]}</p></div><div class="page-heading-actions">${page==='overview'?button('Результаты мероприятия','eventResults','secondary'):''}${button(`${icon('plus')} Изменить показатели`,'adjust','primary')}</div></div>
  ${storageProblem?'<div class="warning">Хранилище недоступно или сохранённый файл повреждён. Экспортируйте данные перед продолжением.</div>':''}
  ${({overview,alliances:alliancesPage,planets:planetsPage,interface:interfacesPage,access:catalogPage,upgrades:catalogPage,equipment:catalogPage,history:historyPage})[page]()}
 </main></div><dialog id="modal"></dialog>`;
 applyAccessControls();
}
function overview(){
 return `<section class="overview-alliances"><div class="section-heading"><h2>Все альянсы <span class="muted-number">${state.alliances.length}</span></h2><button class="text-button" data-page="alliances">Открыть альянс ${icon('arrow')}</button></div><div class="alliance-grid">${state.alliances.map(allianceCard).join('')||empty('Нет альянсов','Добавьте первый альянс смены.',button('Добавить альянс','addAlliance'))}</div></section>`;
}
function stat(i,value,label,note,color){return `<article class="stat panel"><span class="stat-icon ${color}">${icon(i)}</span><strong class="stat-value">${value}</strong><h3>${label}</h3><p>${note}</p></article>`;}
function earningsDescription(a){return `${num(a.earnedCaps)} ${a.earnedCapsKnown===false?'получено с начала учёта':'заработано за смену'}`;}
function levelDescription(a){const bonus=a.bonusLevels||0;return `${allianceLevel(state,a)-bonus} по опыту${bonus?` + ${bonus} найдено на карте`:''}`;}
function sourceNotesPanel(a){
 const labels={level:'Уровень в таблице',cadia:'Кадия',fenris:'Фенрис',cronus:'Кронус',missing:'Не указано в источнике'};
 const rows=Object.entries(a.sourceNotes||{}).filter(([key,value])=>labels[key]&&value);
 return rows.length?`<details class="source-notes panel"><summary>${icon('book')} Заметки из таблицы</summary><dl>${rows.map(([key,value])=>`<div><dt>${labels[key]}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></details>`:'';
}
function planetSourceNote(a){const note=a.sourceNotes?.[planet];if(!note||/^\s*\d+(?:\.0+)?\s*$/.test(note)||planet==='cronus'&&a.planets.cronus.shuttles.some(r=>r.note===note))return '';return `<div class="source-note">${icon('book')}<div><strong>Бонусы и заметки</strong><p>${esc(note)}</p></div></div>`;}
function bonusLevelsModal(){const a=active();if(!a)return;modal(`Найденные уровни · ${esc(a.name)}`,`${intro(`Уровень ${allianceLevel(state,a)}: ${levelDescription(a)}. Найденные уровни не меняют опыт и сохраняются при его начислении.`)}<form data-form="bonusLevels">${field('Дополнительные уровни с карты',number('bonusLevels',a.bonusLevels||0))}${field('Причина',input('reason','','required maxlength="160" placeholder="Найдена награда +1 уровень"'))}${submit('Сохранить найденные уровни')}</form>`);}
function allianceCard(a){
 const xp=xpProgress(state,a);
 return `<button class="alliance-card panel ${a.id===activeId?'selected':''}" data-action="selectAlliance" data-id="${a.id}" aria-label="Открыть альянс ${esc(a.name)}">
  <div class="alliance-top"><div class="alliance-identity"><span class="emblem ${a.color}">${emblem(a.color)}</span><h3>${esc(a.name)}</h3></div><span class="level-pill ${a.color}">Уровень ${xp.level}</span></div>
  <div class="alliance-resources"><div><span>Крышечки</span><strong>${num(a.caps)}</strong></div><div><span>Опыт</span><strong>${num(a.xp)}</strong></div></div>
  <div class="xp-label"><span>${xp.next===undefined?'Все уровни пройдены':`До уровня ${xp.level+1}`}</span><span>${xp.next===undefined?'':`${num(xp.remaining)} опыта`}</span></div><div class="track ${a.color}"><i style="width:${xp.percent}%"></i></div>
  <div class="role-strip">${roles.map(r=>`<span title="${r.name}: ${a.functions[r.id]} ${r.id==='raiders'?'ОД':'репутации'}"><span class="role-mini ${r.color}">${icon(r.icon)}</span><small class="role-name">${r.name}</small><strong>${a.functions[r.id]} <em>${r.id==='raiders'?'ОД':'реп.'}</em></strong></span>`).join('')}</div>
 </button>`;
}
function eventRow(e){const a=state.alliances.find(a=>a.id===e.allianceId);const i={reward:'coin',purchase:'box',craft:'wrench',planet:'orbit',interface:'bolt',event:'trophy',inventory:'box',update:'edit'}[e.kind]||'spark';return `<div class="event-row"><span class="event-icon ${a?.color||'blue'}">${icon(i)}</span><div><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p><small>${esc(a?.name||'Альянс')} · Сол ${e.sol} · ${new Date(e.time).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div></div>`;}
function searchBox(placeholder){return `<label class="search">${icon('search')}<input id="search" type="search" placeholder="${placeholder}" aria-label="Поиск" value="${esc(search)}"></label>`;}
function alliancesPage(){const a=active();return `<div class="toolbar">${searchBox('Найти альянс или участника…')}${button(`${icon('plus')} Новый альянс`,'addAlliance')}</div><div class="alliance-tabs">${state.alliances.filter(a=>match(a.name)||a.children.some(c=>match(c.name))).map(a=>`<button class="alliance-tab ${a.id===activeId?'selected':''}" data-action="activate" data-id="${a.id}"><span class="emblem mini ${a.color}">${emblem(a.color)}</span>${esc(a.name)}<span>УР. ${allianceLevel(state,a)}</span></button>`).join('')||'<p class="panel-note">Ничего не найдено</p>'}</div>${a?allianceDetail(a):empty('Ваши альянсы скоро выйдут на связь','Создайте первую команду.',button('Новый альянс','addAlliance'))}`;}
function allianceDetail(a){const xp=xpProgress(state,a);return `<section class="alliance-banner panel"><span class="emblem large ${a.color}">${emblem(a.color)}</span><div><span class="eyebrow">${a.children.length?`${a.children.length} участников`:'Альянс'}</span><h2>${esc(a.name)}</h2>${a.motto&&a.motto!=='К новым мирам — вместе'?`<p>${esc(a.motto)}</p>`:''}</div>${button(`${icon('edit')} Редактировать`,'editAlliance','secondary',`data-id="${a.id}"`)}</section><section class="detail-stats">${stat('coin',num(a.caps),'Крышечек на балансе',earningsDescription(a),'orange')}${stat('spark',num(a.xp),'Опыт альянса',xp.next===undefined?'Все пороги пройдены':`${num(xp.remaining)} до следующего уровня`,'purple')}${stat('trending',xp.level,'Уровень альянса','Опыт и находки на карте','blue')}</section><div class="level-summary"><p>${icon('trending')} ${esc(levelDescription(a))}</p>${button('Найденные уровни','bonusLevels','secondary')}</div>${sourceNotesPanel(a)}<div class="section-heading"><h2>Подфункции альянса</h2><span class="section-note">Репутация и очки действий</span></div><div class="functions-grid">${roles.map(r=>`<button class="function-card panel" data-action="adjustRole" data-role="${r.id}"><span class="stat-icon ${r.color}">${icon(r.icon)}</span><h3>${r.name}</h3><strong>${num(a.functions[r.id])}</strong><span>${r.id==='raiders'?'Очки действий':'Репутация'}</span><small>Изменить ${icon('plus')}</small></button>`).join('')}</div><div class="detail-columns"><section class="panel"><div class="section-heading"><h2>Искатели альянса <span class="muted-number">${a.children.length}</span></h2><button class="text-button" data-action="addChild">${icon('plus')}Участник</button></div>${a.children.filter(c=>match(c.name)||match(a.name)).map(c=>`<div class="child-row"><span class="child-avatar ${roles.find(r=>r.id===c.role).color}">${esc(c.name[0])}</span><div><strong>${esc(c.name)}</strong><small>${roles.find(r=>r.id===c.role).name} · ${num(c.xp)} личного опыта</small></div><button class="icon-button" data-action="editChild" data-id="${c.id}" aria-label="Редактировать ${esc(c.name)}">${icon('edit')}</button><button class="icon-button" data-action="childXP" data-id="${c.id}" aria-label="Начислить опыт: ${esc(c.name)}">${icon('plus')}</button></div>`).join('')||`<p class="panel-note">${a.sourceNotes?'Список участников пока не заполнен.':'Добавьте участников вашей команды.'}</p>`}<p class="fine-note">Личный опыт также увеличивает общий опыт альянса.</p></section><section class="panel"><div class="section-heading"><h2>Во владении альянса</h2><button class="text-button" data-action="inventory">Инвентарь ${icon('arrow')}</button></div><div class="ownership-list">${a.upgrades.map(id=>getItem(state,id)).filter(Boolean).map(i=>`<div>${icon('check')}<span>${esc(i.name)}</span><span class="tag">ПРОКАЧКА</span></div>`).join('')||`<p class="panel-note">${a.sourceNotes?'Список улучшений пока не заполнен.':'Улучшения пока не установлены.'}</p>`}${a.access.map(id=>getItem(state,id)).filter(Boolean).map(i=>`<div>${icon('key')}<span>${esc(i.name)}</span><span class="tag">ЭТОТ СОЛ</span></div>`).join('')}</div><div class="resource-mini"><span>${icon('box')} ${Object.values(a.inventory).reduce((n,v)=>n+v,0)} предметов и инструментов</span>${button('Открыть эквип','gotoEquipment','secondary')}</div></section></div>`;}
function planetTabs(){return `<div class="segment-tabs planet-tabs">${planets.map(p=>`<button class="${planet===p.id?'selected':''}" data-action="planetTab" data-planet="${p.id}">${icon(p.icon)}${p.name}</button>`).join('')}</div>`;}
function planetsPage(){const a=active(),p=planets.find(p=>p.id===planet);return `${planetTabs()}${a?`<section class="planet-banner panel"><div><span class="eyebrow">${esc(a.name)} · ПЛАНЕТАРНАЯ ОПЕРАЦИЯ</span><h2>${p.name}</h2></div></section><div class="section-heading"><h2>${planet==='cadia'?'Захваченные аванпосты':planet==='fenris'?'Исследованные территории':'Шаттлы во владении'} <span class="muted-number">${planetRecords(a).length}</span></h2>${button(`${icon('plus')} ${planet==='cadia'?'Захватить аванпост':planet==='fenris'?'Отметить исследование':'Добавить шаттл'}`,'addPlanet')}</div>${planet==='cadia'?`<div class="planet-ap">${icon('bolt')} <span>Очки действий на Кадии</span><strong>${a.planets.cadia.actionPoints}</strong><button class="text-button" data-action="adjustAP">Изменить ${icon('edit')}</button></div>`:''}${planetSourceNote(a)}<div class="planet-records">${planetRecords(a).map(r=>planetRecord(a,r)).join('')||empty('Этот мир ждёт ваших открытий','Запишите первую операцию альянса.')}</div>`:empty('Сначала создайте альянс','Прогресс на каждой планете учитывается отдельно для каждого альянса.',button('Добавить альянс','addAlliance'))}`;}
function planetRecords(a){return planet==='cadia'?a.planets.cadia.outposts:planet==='fenris'?a.planets.fenris.territories:a.planets.cronus.shuttles;}
function planetRecord(a,r){
 const p=planets.find(p=>p.id===planet);
 const bonus=planet==='cadia'?(r.bonusKnown===false?'<p class="unknown-value">Бонус не указан.</p>':`<div class="bonus-list"><span>${icon('coin')} +${r.bonus.caps} крышечек</span><span>${icon('spark')} +${r.bonus.xp} опыта</span><span>${icon('bolt')} +${r.bonus.actionPoints} ОД на Кадии</span>${r.bonus.toolId?`<span>${icon('wrench')} ${esc(getItem(state,r.bonus.toolId).name)} ×${r.bonus.quantity}</span>`:''}</div>${button(`${icon(r.claimed?'check':'plus')} ${r.claimed?'Бонус начислен':'Начислить бонус'}`,'claimBonus',r.claimed?'completed':'secondary',`data-id="${r.id}" ${r.claimed?'disabled':''}`)}`):`<p>${esc(r.note)||'Запись в журнале экспедиции'}</p>`;
 return `<article class="panel planet-record"><div class="section-heading"><span class="record-icon ${p.color}">${icon(p.icon)}</span><span class="tag">${planet==='cadia'?'ЗАХВАЧЕН':planet==='fenris'?'ИССЛЕДОВАНО':'ВО ВЛАДЕНИИ'}</span><button class="icon-button" data-action="removePlanet" data-id="${r.id}" aria-label="Снять с учёта ${esc(r.name)}">${icon('trash')}</button></div><h3>${esc(r.name)}</h3>${bonus}</article>`;
}
function interfacesPage(){return `<div class="interface-grid">${state.alliances.map(a=>{
 const f=a.interface,known=f.maxChargeKnown!==false,pct=known?f.charge/f.maxCharge*100:0;
 return `<article class="interface-card panel">
  <div class="section-heading interface-heading"><span class="emblem mini ${a.color}">${emblem(a.color)}</span><h2>${esc(a.name)}</h2><button class="icon-button" data-action="editInterface" data-id="${a.id}" aria-label="Редактировать интерфейс ${esc(a.name)}">${icon('edit')}</button></div>
  ${f.name!==`Интерфейс «${a.name}»`?`<p class="interface-device">${esc(f.name)}</p>`:''}
  <div class="interface-values"><div><span>Заряд</span><strong>${num(f.charge)}${known?`<small> / ${num(f.maxCharge)}</small>`:''}</strong></div><div><span>Гравитоны</span><strong>${num(f.gravitons)}</strong></div><div><span>Стойкость</span><strong class="${f.resilienceKnown===false?'metric-unknown':''}">${f.resilienceKnown===false?'Не указана':num(f.resilience)}</strong></div></div>
  ${known?`<div class="track charge-meter ${a.color}" aria-label="Заряд ${Math.round(pct)} процентов"><i style="width:${pct}%"></i></div>`:'<p class="unknown-value">Ёмкость не указана</p>'}
  <p class="graviton-purchases">Куплено за смену: ${f.gravitonsPurchased||0} из 10 гравитонов</p>
  ${button('Обновить показатели','editInterface','secondary',`data-id="${a.id}"`)}
 </article>`;
 }).join('')||empty('Нет интерфейсов','Создайте альянс, чтобы добавить его показатели.',button('Создать альянс','addAlliance'))}</div>`;
}
function catalogPage(){const category=page==='equipment'?equipmentTab:page,items=allItems(state).filter(i=>i.category===category),a=active();return `${page==='equipment'?`<div class="segment-tabs"><button data-action="equipmentTab" data-tab="equipment" class="${equipmentTab==='equipment'?'selected':''}">${icon('box')} Предметы и способности <span>${allItems(state).filter(i=>i.category==='equipment').length}</span></button><button data-action="equipmentTab" data-tab="tools" class="${equipmentTab==='tools'?'selected':''}">${icon('wrench')} Инструменты <span>${allItems(state).filter(i=>i.category==='tools').length}</span></button></div>`:''}<div class="catalog-context"><span>${icon('coin')} Баланс ${a?`альянса <strong>${esc(a.name)}</strong>`:'не выбран'}: <b>${a?num(a.caps):'—'}</b> крышечек</span><div>${button(`${icon('box')} Инвентарь`,'inventory')}${button(`${icon('plus')} Новый товар`,'addItem')}</div></div><div class="toolbar">${searchBox('Название, эффект или рецепт…')}<div class="filter-chips">${[['all','Все'],['owned','Во владении'],['affordable','Можно купить']].map(([id,title])=>`<button class="${catalogFilter===id?'selected':''}" data-action="catalogFilter" data-filter="${id}">${title}</button>`).join('')}</div></div>${category==='tools'?'<div class="info-note">Число у инструмента — его уровень. При крафте ингредиенты расходуются.</div>':''}<div class="catalog-grid">${items.filter(i=>match(i.name)||match(i.effect)||match(i.recipeText)).filter(i=>catalogFilter==='owned'?a&&owned(state,a,i)>0:catalogFilter==='affordable'?a&&i.price!==null&&a.caps>=i.price:true).map(i=>itemCard(i,a)).join('')||empty('По этому курсу ничего не найдено','Измените поиск или добавьте свой товар.')}</div>`;}
function itemCard(i,a){
 const have=a?owned(state,a,i):0,hasRecipe=i.recipeText&&i.recipeText!=='-',review=i.recipeIssue||i.needsRecipeReview&&!i.recipeConfirmed;
 return `<article class="item-card panel"><div class="item-card-top"><h3>${esc(i.name)}</h3><div class="item-card-controls">${i.category==='tools'?`<span class="tag">Уровень ${i.toolLevel}</span>`:''}<button class="icon-button" data-action="editItem" data-id="${i.id}" aria-label="Настроить ${esc(i.name)}">${icon('settings')}</button></div></div>
  <p class="item-effect">${esc(i.effect)}</p>
  ${hasRecipe?`<details class="recipe-preview"><summary>Рецепт крафта${review?'<small> · уточнить состав</small>':''}</summary><p>${esc(i.recipeText).replace(/\n/g,'<br>')}</p>${i.recipeIssue?`<small>${esc(i.recipeIssue)}</small>`:review?'<small>Перед крафтом организатор подтверждает состав.</small>':''}</details>`:''}
  <div class="item-bottom"><div class="price">${i.price===null?'<span class="unknown-price">Цена не задана</span>':`<strong>${num(i.price)}</strong><span>крышечек</span>`}</div><span class="owned-label ${have?'has-item':''}">${have?`${icon('check')} ${i.kind==='graviton'?`${have} гравитонов`:i.category==='upgrades'?'Установлено':i.category==='access'?'Доступ открыт':`Есть: ${have}`}`:''}</span></div>
  <div class="item-actions">${button(!isAdmin()||i.price===null?'Подробнее':'Купить','item','secondary',`data-id="${i.id}"`)}${i.recipe||i.recipeIssue?button('Крафт','craft','ghost',`data-id="${i.id}"`):''}</div>
 </article>`;
}
function historyPage(){return `<div class="toolbar">${searchBox('Найти событие или альянс…')}<div class="toolbar-actions">${button(`${icon('trophy')} Результаты мероприятия`,'eventResults')}${button(`${icon('download')} Экспорт`,'export')}</div></div><div class="panel history-panel">${state.events.filter(e=>match(e.title)||match(e.detail)||match(state.alliances.find(a=>a.id===e.allianceId)?.name||'')).map(eventRow).join('')||empty('Тишина в эфире','Запишите первые результаты вашей смены.')}</div>`;}
// Modal forms use the same model functions as automated domain tests.
function modal(title,content){const d=document.querySelector('#modal');d.innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></div>${content}`;applyAccessControls();d.showModal();}
const field=(label,html)=>`<label class="field"><span>${label}</span>${html}</label>`;
const input=(name,value='',attrs='')=>`<input name="${name}" value="${esc(value)}" ${attrs}>`;
const number=(name,value=0,min=0,max=1000000000)=>input(name,value,`type="number" min="${min}" max="${max}" required`);
const submit=(label)=>`<p class="form-error" role="alert"></p><button class="button primary submit" type="submit">${label} ${icon('check')}</button>`;
const intro=s=>`<p class="modal-intro">${s}</p>`;
function requireAlliance(){if(!active()){toast('Сначала создайте альянс.',true);return false;}return true;}
function adjustModal(resource='caps',childId=''){if(!requireAlliance())return;const a=active();modal('Обновить показатели',`${intro('Начисление и списание ресурсов записываются в хронику. Личный опыт также влияет на общий опыт альянса.')}<form data-form="adjust">${field('Альянс',`<select name="allianceId" id="adjust-alliance">${allianceOptions()}</select>`)}${field('Показатель',`<select name="resource" id="adjust-resource">${[['caps','Крышечки'],['xp','Опыт'],...roles.map(r=>[r.id,`${r.name} · ${r.id==='raiders'?'ОД':'репутация'}`]),['charge','Заряд интерфейса'],['resilience','Стойкость'],['cadiaAP','ОД на Кадии']].map(([id,title])=>`<option value="${id}" ${resource===id?'selected':''}>${title}</option>`).join('')}</select>`)}<div id="child-field" ${resource!=='xp'?'hidden':''}>${field('Получатель опыта',`<select name="childId" id="adjust-child">${childOptions(a,childId)}</select>`)}</div>${field('Изменение (+ начислить, − списать)',number('amount',50,-1000000000))}${field('Причина',input('reason','',`placeholder="За мероприятие, помощь альянсу…" maxlength="160" required`))}${submit('Сохранить изменение')}</form>`);}
function childOptions(a,childId=''){return '<option value="">Всему альянсу</option>'+a.children.map(c=>`<option value="${c.id}" ${c.id===childId?'selected':''}>${esc(c.name)}</option>`).join('');}
function allianceModal(edit=false){const a=edit?active():null;modal(edit?'Настройки альянса':'Новый альянс',`<form data-form="${edit?'editAlliance':'addAlliance'}">${field('Название альянса',input('name',a?.name||'','maxlength="60" required placeholder="Например, Орион"'))}${field('Девиз',input('motto',a?.motto||'К новым мирам — вместе','maxlength="140" required'))}${field('Символ и цвет',`<select name="color">${[['blue','Звезда · Голубой'],['purple','Орбита · Сиреневый'],['orange','Пульсар · Оранжевый'],['green','Щит · Зелёный'],['pink','Кристалл · Розовый']].map(([v,t])=>`<option value="${v}" ${a?.color===v?'selected':''}>${t}</option>`).join('')}</select>`)}${submit(edit?'Сохранить альянс':'Создать альянс')}</form>`);}
function childModal(id){if(!requireAlliance())return;const a=active(),c=id?a.children.find(c=>c.id===id):null;modal(c?'Участник альянса':'Новый искатель',`<form data-form="${c?'editChild':'addChild'}" ${c?`data-id="${c.id}"`:''}>${field('Имя участника',input('name',c?.name||'','maxlength="60" required placeholder="Например, Аня К."'))}${field('Подфункция',`<select name="role">${roles.map(r=>`<option value="${r.id}" ${c?.role===r.id?'selected':''}>${r.name}</option>`).join('')}</select>`)}${intro('Можно использовать имя и первую букву фамилии. Опыт изменяется через начисление показателей.')}${submit(c?'Сохранить':'Добавить участника')}</form>`);}
function eventModal(){if(!requireAlliance())return;modal('Результаты мероприятия',`${intro('Укажите занятые места и фактические награды. Крышечки и опыт будут начислены всем отмеченным альянсам.')}<form data-form="eventResults">${field('Название мероприятия',input('name','','required maxlength="100" placeholder="Например, Большая космическая эстафета"'))}<div class="results-table"><div class="results-head"><span>Альянс</span><span>Место</span><span>Крышечки</span><span>Опыт</span></div>${state.alliances.map((a,i)=>`<div class="result-row"><label><input type="checkbox" name="include-${a.id}" checked><span>${esc(a.name)}</span></label><input type="number" name="place-${a.id}" min="1" max="999" value="${i+1}" aria-label="Место ${esc(a.name)}"><input type="number" name="caps-${a.id}" min="0" max="1000000000" value="0" aria-label="Крышечки ${esc(a.name)}"><input type="number" name="xp-${a.id}" min="0" max="1000000000" value="0" aria-label="Опыт ${esc(a.name)}"></div>`).join('')}</div>${submit('Начислить награды')}</form>`);}
function interfaceModal(id){
 const a=getAlliance(state,id),f=a.interface;
 modal(`Интерфейс · ${esc(a.name)}`,`<form data-form="interface" data-id="${id}">${field('Название интерфейса',input('name',f.name,'maxlength="80" required'))}<div class="two-fields">${field('Текущий заряд',number('charge',f.charge))}${field('Максимальный заряд',number('maxCharge',f.maxCharge,1))}</div><label class="checkbox-field"><input type="checkbox" name="capacityUnknown" ${f.maxChargeKnown===false?'checked':''}> Максимальная ёмкость пока неизвестна</label><div class="two-fields">${field('Гравитоны (общая масса)',number('gravitons',f.gravitons))}${field('Куплено гравитонов за смену',number('gravitonsPurchased',f.gravitonsPurchased||0,0,10))}${field('Стойкость',number('resilience',f.resilience))}</div><label class="checkbox-field"><input type="checkbox" name="resilienceUnknown" ${f.resilienceKnown===false?'checked':''}> Стойкость пока неизвестна</label>${intro('Общая масса не ограничена. В магазине можно купить до 10 гравитонов за смену; найденные и выданные вручную в этот лимит не входят.')}${submit('Обновить интерфейс')}</form>`);
}
function planetModal(){if(!requireAlliance())return;const title=planet==='cadia'?'Захват аванпоста':planet==='fenris'?'Исследование территории':'Шаттл альянса';modal(title,`<form data-form="planet"><span class="pill">${esc(active().name)} · ${planets.find(p=>p.id===planet).name}</span>${field('Название',input('name','','maxlength="80" required'))}${planet==='cadia'?`${intro('Запишите бонус аванпоста. Он начисляется отдельной кнопкой один раз для этой записи.')}<div class="two-fields">${field('Бонус · крышечки',number('caps'))}${field('Бонус · опыт',number('xp'))}${field('Бонус · ОД на Кадии',number('actionPoints'))}${field('Количество инструментов',number('quantity',1,1,999))}</div>${field('Бонус · инструмент',`<select name="toolId"><option value="">Без инструмента</option>${allItems(state).filter(i=>i.category==='tools').map(i=>`<option value="${i.id}">${esc(i.name)} · ур. ${i.toolLevel}</option>`).join('')}</select>`)}`:field(planet==='fenris'?'Что обнаружили':'Описание / статус',`<textarea name="note" rows="3" maxlength="300" placeholder="Заметка организатора"></textarea>`)}${submit('Записать операцию')}</form>`);}
function itemModal(id){const i=getItem(state,id);if(!i)return;const a=active(),have=a?owned(state,a,i):0;modal(esc(i.name),`<span class="pill">${categories[i.category].name}${i.category==='tools'?` · Уровень ${i.toolLevel}`:''}</span>${intro(esc(i.effect))}${i.recipeText&&i.recipeText!=='-'?`<div class="recipe-detail"><strong>Рецепт</strong><p>${esc(i.recipeText).replace(/\n/g,'<br>')}</p></div>`:''}<div class="purchase-summary"><span>${a?`Альянс ${esc(a.name)}`:'Альянс не выбран'}</span><strong>${i.price===null?'Цена не задана':`${num(i.price)} крышечек`}</strong></div>${intro(a?`Баланс: ${num(a.caps)} крышечек.${have?` Во владении: ${have}.`:''}`:'Сначала создайте альянс.')}${i.kind==='graviton'&&a?intro(`Куплено в магазине: ${a.interface.gravitonsPurchased||0} из 10 за смену. Найденные гравитоны не учитываются в лимите.`):''}${!isAdmin()?intro('Покупки и крафт отмечает организатор смены.'):i.price===null?`${intro('Цена не была указана в исходном списке. Организатор может настроить её или выдать предмет за мероприятие.')}${button(`${icon('settings')} Указать цену`,'editItem','secondary',`data-id="${id}"`)}`:`<form data-form="purchase" data-id="${id}">${submit('Подтвердить покупку')}</form>`}<div class="modal-secondary-actions">${i.recipe||i.recipeIssue?button(`${icon('wrench')} Скрафтить`,'craft','secondary',`data-id="${id}"`):''}${button('Выдать вручную','grant','ghost',`data-id="${id}"`)}</div>${intro('Эффекты предметов учитываются организатором во время игры. Покупка помещает предмет в инвентарь; способности не применяются автоматически.')}`);}
function craftModal(id){if(!requireAlliance())return;const i=getItem(state,id),a=active();if(!i)return;if(i.recipeIssue||!i.recipe){modal('Рецепт требует настройки',`${intro(esc(i.recipeIssue||'Рецепт отсутствует.'))}${button('Настроить рецепт','editItem','primary',`data-id="${id}"`)}`);return;}if(i.needsRecipeReview&&!i.recipeConfirmed){modal('Подтвердите состав рецепта',`${intro('В исходном списке ингредиенты разделены строками или знаками. Проверьте перенесённый состав перед первым крафтом.')}${intro(esc(i.recipeText).replace(/\n/g,'<br>'))}${button('Проверить и настроить рецепт','editItem','primary',`data-id="${id}"`)}`);return;}
 let fields='';if(i.recipe.type==='anyTools'){const options=allItems(state).filter(t=>t.category==='tools'&&t.toolLevel>=i.recipe.minLevel&&(a.inventory[t.id]||0)>0);fields=`${intro(`Нужно ${i.recipe.count} инструмента${i.recipe.minLevel?` уровня ${i.recipe.minLevel}+`:''}. Можно использовать два экземпляра одного инструмента, если они есть в инвентаре.`)}${Array.from({length:i.recipe.count},(_,n)=>field(`Инструмент ${n+1}`,`<select name="ingredient-${n}" required><option value="">Выберите инструмент</option>${options.map(t=>`<option value="${t.id}">${esc(t.name)} · ур. ${t.toolLevel} · есть ${a.inventory[t.id]}</option>`).join('')}</select>`)).join('')}`;}else fields=field('Вариант рецепта',`<select name="variant">${i.recipe.variants.map((v,n)=>`<option value="${n}">${v.map(id=>esc(getItem(state,id)?.name||id)).join(' + ')}</option>`).join('')}</select>`);
 modal(`Крафт · ${esc(i.name)}`,`${intro(esc(i.effect))}<div class="warning subtle">Ингредиенты будут израсходованы.${state.rules.craftCostsCaps?` Также списывается цена: ${i.price===null?'не задана':`${num(i.price)} крышечек`}.`:' Крышечки за крафт не списываются (правило меняется в настройках).'}</div><form data-form="craft" data-id="${id}">${fields}<div class="recipe-stock">${i.recipe.type==='specific'?[...new Set(i.recipe.variants.flat())].map(id=>`<span>${esc(getItem(state,id)?.name||id)} <b>${a.inventory[id]||0} шт.</b></span>`).join(''):''}</div>${submit('Скрафтить и списать ингредиенты')}</form>`);
}
function itemSettingsModal(id){const i=getItem(state,id);if(!i)return;const variants=i.recipe?.type==='specific'?i.recipe.variants:[];modal(`Настройки · ${esc(i.name)}`,`<form data-form="itemSettings" data-id="${id}">${field('Цена в крышечках (пусто — не задана)',input('price',i.price===null?'':i.price,'type="number" min="0" max="1000000000"'))}${field('Эффект',`<textarea name="effect" rows="3" maxlength="2000" required>${esc(i.effect)}</textarea>`)}${i.category==='tools'?field('Уровень инструмента',number('toolLevel',i.toolLevel,1,999)):''}<div class="recipe-detail"><strong>Исходный рецепт</strong><p>${esc(i.recipeText||'Не задан').replace(/\n/g,'<br>')}</p></div>${i.recipeIssue?`<div class="warning">${esc(i.recipeIssue)}</div>`:''}${i.recipe?.type==='anyTools'?`${field('Количество инструментов для крафта',number('toolCount',i.recipe.count,1,10))}${field('Минимальный уровень инструмента',number('minLevel',i.recipe.minLevel,0,999))}`:`${variants.length?`<div class="recipe-variants">${variants.map((v,n)=>`<div><span>Вариант ${n+1}</span><p>${v.map(id=>esc(getItem(state,id)?.name||id)).join(' + ')}</p></div>`).join('')}</div>`:''}${field('Заменить рецепт (необязательно)',`<select name="recipeMode"><option value="keep">Сохранить текущий состав</option><option value="replace">Задать новый состав ниже</option><option value="none">Убрать рецепт</option></select>`)}<div class="recipe-edit-fields">${[1,2,3].map(n=>field(`Ингредиент ${n}`,`<select name="recipe-${n}"><option value="">Не выбран</option>${allItems(state).filter(t=>['tools','equipment'].includes(t.category)&&t.id!==id).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select>`)).join('')}</div>`}${i.recipe&&i.recipe.type!=='anyTools'?`<label class="checkbox-field"><input type="checkbox" name="recipeConfirmed" ${i.recipeConfirmed?'checked':''}> Подтверждаю состав и варианты рецепта</label>`:''}${submit('Сохранить настройки товара')}</form>`);}
function grantModal(id){if(!requireAlliance())return;const i=getItem(state,id);modal(`Выдать · ${esc(i.name)}`,`${intro('Ручная выдача за мероприятие или перенос начальных данных. Крышечки не списываются.')}<form data-form="grant" data-id="${id}">${field('Количество',number('quantity',1,1,999))}${field('Причина',input('reason','','required maxlength="160" placeholder="Награда за мероприятие / перенос данных"'))}${submit('Выдать альянсу')}</form>`);}
function inventoryModal(){if(!requireAlliance())return;const a=active(),items=Object.entries(a.inventory).map(([id,n])=>({item:getItem(state,id),n}));modal(`Инвентарь · ${esc(a.name)}`,`${intro('Предметы и инструменты альянса. При крафте ингредиенты списываются автоматически.')}<div class="inventory-list">${items.map(({item:i,n})=>`<div class="inventory-row"><span class="item-icon ${i.category==='tools'?'green':'purple'}">${icon(i.category==='tools'?'wrench':'box')}</span><div><strong>${esc(i.name)}</strong><small>${i.category==='tools'?`Уровень ${i.toolLevel}`:'Предмет / способность'}</small></div><b>×${n}</b><button class="icon-button" data-action="spendItem" data-id="${i.id}" aria-label="Списать ${esc(i.name)}">${icon('trash')}</button></div>`).join('')||'<p class="panel-note">Инвентарь пуст. Купите или выдайте первые предметы.</p>'}</div>`);}
function spendModal(id){const i=getItem(state,id);modal(`Списать · ${esc(i.name)}`,`<form data-form="spend" data-id="${id}">${field('Количество',number('quantity',1,1,owned(state,active(),i)))}${field('Причина',input('reason','','required maxlength="160" placeholder="Использован в игре / потерян"'))}${submit('Подтвердить списание')}</form>`);}
function addItemModal(){const category=page==='equipment'?equipmentTab:categories[page]?page:'equipment';modal('Новый товар смены',`<form data-form="addItem">${field('Раздел',`<select name="category">${Object.entries(categories).map(([id,c])=>`<option value="${id}" ${id===category?'selected':''}>${c.name}</option>`).join('')}</select>`)}${field('Название',input('name','','maxlength="100" required'))}${field('Цена (пусто — не задана)',input('price','','type="number" min="0" max="1000000000"'))}${field('Эффект',`<textarea name="effect" rows="3" required maxlength="2000"></textarea>`)}${field('Уровень, если это инструмент',number('toolLevel',1,1,999))}${submit('Добавить товар')}</form>`);}
function settingsModal(){modal('Правила вашей смены',`<form data-form="settings">${field('Название смены',input('name',state.shift.name,'required maxlength="80"'))}<div class="two-fields">${field('Текущий сол',number('day',state.shift.day,1,365))}${field('Солов в смене',number('duration',state.shift.duration,1,365))}</div>${field('Пороги опыта для уровней 1, 2, 3…',input('levelThresholds',state.rules.levelThresholds.join(', '),'required'))}${intro('Пороги начинаются с 0 и растут: например 0, 500, 1000. Укажите пороги вашей смены. Уровни за опыт пересчитаются, найденные на карте уровни сохранятся.')}<label class="checkbox-field"><input name="craftCostsCaps" type="checkbox" ${state.rules.craftCostsCaps?'checked':''}> При крафте также списывать цену в крышечках</label>${intro('Ингредиенты крафта всегда расходуются. Покупка за крышечки и крафт доступны как отдельные операции. При переходе к другому солу список купленных доступов очищается, история покупок сохраняется.')}${submit('Сохранить правила')}</form><div class="settings-backup"><h3>Сохранение и перенос</h3>${intro('Изменения сохраняются на сервере и видны зрителям. Сохраняйте резервные копии перед переносом или очисткой данных.')}<div class="backup-actions">${button(`${icon('download')} Экспорт JSON`,'export')}${button('Загрузить копию','import')}${button('HTML для зрителей','downloadSnapshot')}${hasLegacy?button('Копия прежнего прототипа','exportLegacy','ghost'):''}</div><input type="file" id="import-file" accept=".json,application/json" hidden><button class="text-button reset-link" data-action="reset">Начать чистую космическую смену</button></div>`);}
function downloadJSON(data,name){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия выгружена.');}
function exportData(){downloadJSON(state,'genesis-backup.json');}
async function handleAction(b){const {action,id,role,child}=b.dataset;if(!isAdmin()&&!readActions.has(action))throw Error('Редактирование доступно только организатору.');
 if(action==='noop')return;
 if(action==='login')return loginModal();
 if(action==='logout'){await api('/api/logout',{method:'POST',body:'{}'});auth={role:'viewer',configured:true};render();toast('Вы вышли. Теперь доступен только просмотр.');return;}
 if(action==='downloadSnapshot'){const a=document.createElement('a');a.href='/readonly.html';a.download='genesis-readonly.html';a.click();return;}
 if(action==='close')document.querySelector('#modal').close();
 if(action==='menu')document.querySelector('.sidebar').classList.toggle('mobile-open');
 if(action==='settings')settingsModal();
 if(action==='adjust')adjustModal();
 if(action==='bonusLevels')bonusLevelsModal();
 if(action==='adjustRole')adjustModal(role);
 if(action==='adjustAP')adjustModal('cadiaAP');
 if(action==='childXP')adjustModal('xp',id);
 if(action==='addAlliance')allianceModal();
 if(action==='editAlliance')allianceModal(true);
 if(action==='selectAlliance'){activeId=id;navigate('alliances');}
 if(action==='activate'){activeId=id;render();}
 if(action==='addChild')childModal();
 if(action==='editChild')childModal(id);
 if(action==='eventResults')eventModal();
 if(action==='openPlanet'){planet=b.dataset.planet;navigate('planets');}
 if(action==='planetTab'){planet=b.dataset.planet;render();}
 if(action==='addPlanet')planetModal();
 if(action==='claimBonus'){await mutate(()=>claimOutpostBonus(state,activeId,id));render();toast('Бонус аванпоста начислен.');}
 if(action==='removePlanet')modal('Снять объект с учёта?',`${intro('Запись будет удалена из текущего прогресса планеты. Ранее начисленные бонусы не отменяются.')}<div class="backup-actions">${button('Отмена','close')}${button('Подтвердить','confirmRemovePlanet','primary',`data-id="${id}"`)}</div>`);
 if(action==='confirmRemovePlanet'){await mutate(()=>removePlanetRecord(state,activeId,planet,id));render();toast('Объект снят с учёта.');}
 if(action==='editInterface')interfaceModal(id);
 if(action==='equipmentTab'){equipmentTab=b.dataset.tab;search='';catalogFilter='all';render();}
 if(action==='catalogFilter'){catalogFilter=b.dataset.filter;render();}
 if(action==='item')itemModal(id);
 if(action==='editItem')itemSettingsModal(id);
 if(action==='craft')craftModal(id);
 if(action==='grant')grantModal(id);
 if(action==='inventory')inventoryModal();
 if(action==='spendItem')spendModal(id);
 if(action==='gotoEquipment')navigate('equipment');
 if(action==='addItem')addItemModal();
 if(action==='export')exportData();
 if(action==='exportLegacy'){try{downloadJSON(localStorage.getItem(LEGACY_KEY),'smena-legacy-backup.json');}catch{toast('Хранилище недоступно.',true);}}
 if(action==='import')document.querySelector('#import-file').click();
 if(action==='reset')modal('Начать чистую смену?',`${intro('Все альянсы, участники, планетарный прогресс, инвентари и события будут удалены из этого браузера. Каталоги, цены и правила вашей смены сохранятся. Выгрузите копию перед очисткой.')}<div class="backup-actions">${button('Экспортировать данные','export')}${button('Отмена','close')}</div>${button('Удалить данные и начать смену','confirmReset','primary submit')}`);
 if(action==='confirmReset'){await mutate(()=>{state={...state,alliances:[],events:[]};});activeId='';render();toast('Создайте ваши альянсы — новая смена начинается.');}
}
document.addEventListener('click',async e=>{const p=e.target.closest('[data-page]');if(p){navigate(p.dataset.page);return;}const b=e.target.closest('[data-action]');if(b)try{await handleAction(b);}catch(err){toast(err.message,true);}if(e.target.id==='modal'){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();const el=document.querySelector('#search');el.focus();try{el.setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('change',async e=>{
 if(e.target.id==='active-alliance'){activeId=e.target.value;render();}
 if(e.target.id==='adjust-resource'){document.querySelector('#child-field').hidden=e.target.value!=='xp';if(e.target.value!=='xp')document.querySelector('#adjust-child').value='';}
 if(e.target.id==='adjust-alliance'){document.querySelector('#adjust-child').innerHTML=childOptions(getAlliance(state,e.target.value));}
 if(e.target.id==='import-file'&&e.target.files[0]){try{if(!isAdmin())throw Error('Только администратор может импортировать данные.');const file=e.target.files[0];if(file.size>5000000)throw Error('Максимальный размер копии — 5 МБ.');const data=JSON.parse(await file.text());if(!validateState(data))throw Error('Это не корректная резервная копия космической смены. Прежний лесной прототип использует другой формат.');modal('Восстановить космическую смену?',`${intro(`В копии «${esc(data.shift.name)}»: ${data.alliances.length} альянсов и ${data.events.length} событий. Текущие данные и настройки будут заменены.`)}<div class="backup-actions">${button('Экспорт текущих данных','export')}${button('Отмена','close')}</div><button class="button primary submit" id="confirm-import">Восстановить копию</button>`);document.querySelector('#confirm-import').onclick=async()=>{try{await mutate(()=>{state=data;});activeId=state.alliances[0]?.id||'';render();toast('Смена восстановлена.');}catch(err){toast(err.message,true);}};}catch(err){toast(err.message,true);}}
});
function processForm(kind,data,form){
 const a=active();
 if(kind==='adjust')adjustResource(state,{...data,childId:data.resource==='xp'?data.childId:''});
 if(kind==='addAlliance'){const name=text(data.name,'Название',60);if(state.alliances.some(a=>a.name.toLowerCase()===name.toLowerCase()))throw Error('Альянс с таким названием уже существует.');const next=createAlliance(name,data.motto,data.color);state.alliances.push(next);activeId=next.id;page='alliances';log(state,next.id,'Альянс на связи',next.name);}
 if(kind==='editAlliance'){const name=text(data.name,'Название',60),motto=text(data.motto,'Девиз',140);if(state.alliances.some(x=>x.id!==a.id&&x.name.toLowerCase()===name.toLowerCase()))throw Error('Название уже занято.');a.name=name;a.motto=motto;a.color=data.color;log(state,a.id,'Обновлён альянс',name);}
 if(kind==='addChild'){a.children.push({id:uid(),name:text(data.name,'Имя',60),role:data.role,xp:0});log(state,a.id,'Новый искатель',data.name);}
 if(kind==='editChild'){const child=a.children.find(c=>c.id===form.dataset.id);child.name=text(data.name,'Имя',60);child.role=data.role;log(state,a.id,'Обновлён участник',child.name);}
 if(kind==='eventResults')recordEventResults(state,{name:data.name,results:state.alliances.filter(a=>data[`include-${a.id}`]).map(a=>({allianceId:a.id,place:data[`place-${a.id}`],caps:data[`caps-${a.id}`],xp:data[`xp-${a.id}`]}))});
 if(kind==='interface')updateInterface(state,form.dataset.id,{...data,maxChargeKnown:!data.capacityUnknown,resilienceKnown:!data.resilienceUnknown});
  if(kind==='bonusLevels')updateBonusLevels(state,a.id,data);
 if(kind==='planet')addPlanetRecord(state,activeId,planet,data);
 if(kind==='purchase')purchase(state,activeId,form.dataset.id);
 if(kind==='craft'){const i=getItem(state,form.dataset.id);const ingredients=i.recipe.type==='anyTools'?Array.from({length:i.recipe.count},(_,n)=>data[`ingredient-${n}`]):i.recipe.variants[Number(data.variant)];craft(state,activeId,i.id,ingredients);}
 if(kind==='grant')grantItem(state,activeId,form.dataset.id,data.quantity,data.reason);
 if(kind==='spend')removeInventory(state,activeId,form.dataset.id,data.quantity,data.reason);
 if(kind==='settings')updateSettings(state,data);
 if(kind==='addItem'){const price=data.price===''?null:integer(data.price,'Цена'),category=data.category;if(!categories[category])throw Error('Выберите раздел.');const item={id:`custom-${uid()}`,category,name:text(data.name,'Название',100),price,effect:text(data.effect,'Эффект',2000),recipeText:'-',recipe:null};if(category==='tools')item.toolLevel=integer(data.toolLevel,'Уровень',1,999);state.customItems.push(item);page=category==='tools'?'equipment':category;if(category==='tools')equipmentTab='tools';}
 if(kind==='itemSettings'){
  const id=form.dataset.id,i=getItem(state,id),changes={price:data.price===''?null:integer(data.price,'Цена'),effect:text(data.effect,'Эффект',2000)};
  if(i.category==='tools')changes.toolLevel=integer(data.toolLevel,'Уровень',1,999);
  if(i.recipe?.type==='anyTools'){changes.recipe={type:'anyTools',count:integer(data.toolCount,'Количество',1,10),minLevel:integer(data.minLevel,'Минимальный уровень',0,999)};changes.recipeText=`Любые ${changes.recipe.count} инструмента${changes.recipe.minLevel?` уровня ${changes.recipe.minLevel}+`:''}`;}
  else if(data.recipeMode==='none'){changes.recipe=null;changes.recipeText='-';changes.recipeIssue=null;changes.needsRecipeReview=false;}
  else if(data.recipeMode==='replace'){const ingredients=[data['recipe-1'],data['recipe-2'],data['recipe-3']].filter(Boolean);if(!ingredients.length)throw Error('Выберите хотя бы один ингредиент.');changes.recipe={type:'specific',variants:[ingredients]};changes.recipeText=ingredients.map(id=>getItem(state,id).name).join(' + ');changes.recipeIssue=null;changes.needsRecipeReview=false;changes.recipeConfirmed=true;}
  else if(i.recipe){changes.recipeConfirmed=data.recipeConfirmed==='on';}
  state.itemOverrides[id]={...state.itemOverrides[id],...changes};
 }
}
async function mutate(change){
 if(!isAdmin())throw Error('Войдите как организатор.');if(busy)throw Error('Дождитесь сохранения предыдущего изменения.');
 busy=true;const previous=structuredClone(state);try{change();await save();}catch(err){state=previous;if(err.status===401){auth={role:'viewer',configured:true};render();}throw err;}finally{busy=false;}
}
document.addEventListener('submit',async e=>{
 const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),kind=form.dataset.form;
 const submitButton=form.querySelector('.submit');submitButton.disabled=true;
 try{
  if(kind==='login'){const result=await api('/api/login',{method:'POST',body:JSON.stringify({password:data.password})});auth={...result,configured:true};await refreshRemote(true);render();toast('Вы вошли как организатор.');return;}
  await mutate(()=>processForm(kind,data,form));render();toast(kind==='craft'?'Крафт завершён. Ингредиенты израсходованы.':kind==='purchase'?'Покупка завершена. Крышечки списаны.':kind==='eventResults'?'Награды начислены всем выбранным альянсам.':'Изменения сохранены для всех зрителей.');
 }catch(err){form.querySelector('.form-error').textContent=err.message;if(!form.isConnected)toast(err.message,true);}finally{submitButton.disabled=false;}
});
window.addEventListener('hashchange',()=>{if(location.hash==='#overview')navigate('overview');});
render();
refreshRemote(true);
setInterval(()=>refreshRemote(),10000);
